    {"t": "Select the correctly punctuated sentence.", "o": ["Where are you going?", "Where are you going.", "Where, are you going?", "Where are you going?!"], "a": 0, "e": "A question must end with a single question mark.", "d": 1},
    {"t": "Choose the correct option: 'I ___ my keys; I can't find them anywhere.'", "o": ["lose", "have lost", "am losing", "lost yesterday"], "a": 1, "e": "The present perfect 'have lost' is used for a past action with present relevance.", "d": 2},
    {"t": "Select the correct form: 'By the time we arrived, the film ___.'", "o": ["started", "has started", "had started", "starts"], "a": 2, "e": "Past perfect 'had started' is used for an action completed before another past action.", "d": 2},
    {"t": "Choose the correct option: 'Hardly had he left ___ it began to rain.'", "o": ["than", "when", "then", "as"], "a": 1, "e": "'Hardly...when' is the correct correlative structure.", "d": 3},
    {"t": "Select the correct form: 'No sooner did she arrive ___ the meeting started.'", "o": ["when", "than", "then", "that"], "a": 1, "e": "'No sooner...than' is the correct correlative structure.", "d": 3},
    {"t": "Choose the correct option: 'Scarcely had we sat down ___ the lights went out.'", "o": ["than", "then", "when", "that"], "a": 2, "e": "'Scarcely...when' is the correct structure.", "d": 3},
    {"t": "Select the correct form: 'The boy, ___ father is a doctor, is my friend.'", "o": ["who", "whom", "whose", "which"], "a": 2, "e": "'Whose' shows possession (the boy's father).", "d": 2},
    {"t": "Choose the correct option: 'This is the house ___ I was born.'", "o": ["where", "which", "who", "whom"], "a": 0, "e": "'Where' refers to a place.", "d": 1},
    {"t": "Select the correct form: 'The man ___ you met is my uncle.'", "o": ["which", "whom", "whose", "what"], "a": 1, "e": "'Whom' is the object of 'met', referring to the man.", "d": 2},
    {"t": "Choose the correct option: 'I saw ___ interesting film yesterday.'", "o": ["a", "an", "the", "no article"], "a": 1, "e": "'An' is used before a vowel sound (interesting).", "d": 1},
    {"t": "Select the correct form: 'He is ___ honest man.'", "o": ["a", "an", "the", "no article"], "a": 1, "e": "'An' is used before a silent 'h' vowel sound (honest).", "d": 2},
    {"t": "Choose the correct option: 'She goes to ___ church every Sunday.'", "o": ["a", "an", "the", "no article"], "a": 2, "e": "'The' is used before places of regular institutional activity.", "d": 2},
    {"t": "Select the correct form: '___ Nile is the longest river in Africa.'", "o": ["A", "An", "The", "No article"], "a": 2, "e": "'The' is used before names of rivers.", "d": 1},
